command:
mkdir -p /work/pages-review-probe/src
cat > /work/pages-review-probe/Cargo.toml <<'EOF'
[package]
name = "pages-review-probe"
version = "0.0.0"
edition = "2021"

[dependencies]
discovery_fixture = { path = "/work/crate" }
EOF
cat > /work/pages-review-probe/src/main.rs <<'EOF'
fn main() {
    std::panic::set_hook(Box::new(|_| {}));
    let mut checked = 0;
    for items in 0..=100 {
        for page_size in 0..=100 {
            let expected = if page_size == 0 {
                None
            } else {
                Some(items / page_size + usize::from(items % page_size != 0))
            };
            assert_eq!(discovery_fixture::pages(items, page_size), expected);
            checked += 1;
        }
    }
    println!("{checked} small-input cases passed");
    for (items, page_size) in [(usize::MAX, 2), (1, usize::MAX), (usize::MAX, 1)] {
        let expected = Some(items / page_size + usize::from(items % page_size != 0));
        let actual = std::panic::catch_unwind(|| discovery_fixture::pages(items, page_size));
        println!("pages({items}, {page_size}): expected {expected:?}, observed {actual:?}");
    }
}
EOF
cd /work/pages-review-probe && RUSTUP_AUTO_INSTALL=0 CARGO_NET_OFFLINE=true cargo run --quiet && RUSTUP_AUTO_INSTALL=0 CARGO_NET_OFFLINE=true cargo run --quiet --release
